mapper.select:
SELECT * FROM agri_prod_farm_info
WHERE deleted = 0 AND tenant_id = #{tenantId}

    AND farm_name LIKE CONCAT('%', #{dto.farmName}, '%')


    AND farm_type = #{dto.farmType}


    AND province = #{dto.province}


    AND city = #{dto.city}


    AND status = #{dto.status}


    AND audit_status = #{dto.auditStatus}

ORDER BY create_time DESC
